const k=[{id:"M01",title:"Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivasyon, yaptığın işten keyif almasan da benimsediğin değerleri yansıtabilir. Kuram, özerklik, yeterlik ve ilişki kurmayı temel ihtiyaçlar olarak önerir.",limitation:"Bu, bir kuramı ve araştırmaları anlatan derleme. ODA sorularını sınayan bir deney değil. Özerklik bağımsızlık demek değildir. Ödüller ve yükümlülükler hedefi kendiliğinden sana ait olmaktan çıkarmaz."},{id:"M02",title:"Ntoumanis ve diğerleri · 2021 · İhtiyaçları destekleyen sağlık programları",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 çalışmada, kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında mütevazı ortalama faydalar görüldü. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi.",limitation:"İncelenen sağlık programları birden çok desteği birleştiriyor. Çalışmalar arasında ciddi farklar var; araştırma tasarımları da sınırlı. Değerlerini düşünmeye yönelten tek bir soru bu programların yerini tutmaz. Bulgular her hedef için aynı etkiyi göstermiyor."},{id:"M03",title:"Duckworth ve diğerleri · 2013 · Akademik MCII programı",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"77 beşinci sınıf öğrencisiyle yapılan deneyde, küçük gruplarda birer saatlik üç oturum ve tekrarlanan sonuç, engel, yanıt planları kullanıldı. Bazı akademik sonuçlar iyileşti.",limitation:"Araştırma tek bir okulda yapıldı. Sonraki ölçümlerde gruplar arasında istatistiksel olarak anlamlı fark bulunmadı. Destek ve süre çocuklara özgüydü. Yetişkinlerin telefondaki kısa alıştırması için gösterilmiş bir etki yok."},{id:"M04",title:"Cerasoli, Nicklin ve Ford · 2014 · Motivasyon ve teşvikler",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"183 örneklemde içten gelen motivasyon da teşvikler de performansla ilişkiliydi. İşin niteliği ve miktarı için farklı ilişki biçimleri vardı.",limitation:"Bulgular ilişkileri gösteriyor ve çalışmalara göre değişiyor. Herkes için aynı ödülü öneremez veya takdir gören bir hedefi kişinin benimsemediğini söyleyemeyiz."},{id:"M05",title:"Lally ve diğerleri · 2010 · Alışkanlık oluşumunun modellenmesi",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Verilere iyi uyan 39 otomatikleşme eğrisinde, modelin tahmin ettiği sabit düzeyin yüzde 95’ine ulaşmak için tahmini ortanca süre 66 gündü. Tek bir fırsatı kaçırmak modellenen süreci belirgin biçimde bozmadı.",limitation:"Gözlem 84 gün sürdü; 254 gün, gözlem süresinin dışına uzatılan bir tahmindi. Bu tahminler gözlenmiş tamamlanma tarihleri değil. Herkese uygun bir takvim sunmuyor veya uzun araların etkisini göstermiyor."},{id:"M07",title:"Wood ve Rünger · 2016 · Alışkanlık psikolojisi",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Tekrarlanan ortamlar ve davranışlar alışkanlık öğrenmeyi destekleyebilir. Bilinçli hedefler ve alışkanlık halindeki davranışlar bir arada olabilir.",limitation:"Bu, araştırmaları anlatan bir derleme. ODA’nın küçük adım yöntemini veya bir işe günlük rutinden sonra başlama planını sınayan bir deney değil. Başlama işareti, işi yapacağını garanti etmez. Küçük işler mutlaka büyümek zorunda değil."},{id:"M08",title:"Gollwitzer ve Sheeran · 2006 · Şu olursa bunu yaparım planları",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Belirli “şu olursa bunu yapacağım” planları, 94 bağımsız sınamada hedefe ulaşmayı ortalama olarak artırdı. Geçmiş çalışmalardaki standartlaştırılmış etki d = 0,65 idi.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü yüzde 65 gelişme demek değildir. Planın kesinlikle uygulanacağını göstermez; uygulamadaki hatırlatıcının etkisi için de ölçüt olmaz."},{id:"M10",title:"Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makaledeki 24 bağımsız etkiyi birleştiren analizde, sonuç, engel ve yanıt planları hedefe ulaşmada küçük ile orta arasında ortalama faydalar gösterdi.",limitation:"Çalışmaların farklılığı ve yayın yanlılığına işaret eden bulgular, etki büyüklüğünü yorumlamayı sınırlar. Dileklerin gerçekleşeceğini garanti etmez. Düşüncelerin dış olayları değiştirdiğini veya her WOOP biçiminin doğrulandığını göstermez."},{id:"M13",title:"Harkin ve diğerleri · 2016 · İlerlemeyi izleme",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"İzleme müdahaleleri, 138 rastgele atamalı araştırmada hedefe ulaşmayı ortalama olarak artırdı.",limitation:"Hedefler ve yöntemler farklı. Daha büyük etkilerle ilişkili özellikler, kayıt tutmanın veya paylaşmanın tek başına bu etkilere neden olduğunu göstermez. Haftalık değerlendirmenin en iyi sıklık olduğunu ya da herkesle paylaşman gerektiğini söyleyemeyiz."},{id:"M15",title:"Fogg · Tiny Habits tasarım adımları",url:"https://tinyhabits.com/design/",type:"technique",finding:"Fogg’un önerdiği yöntem, mevcut bir günlük rutini çok küçük bir davranışla eşleştirir. İşlemeyen eşleşmeleri yeniden düzenlemeyi önerir.",limitation:"Bu sayfada yöntemin bütünü için kontrollü bir etki tahmini yok. Kutlamanın şart olduğunu, bir dakikadan kısa sürenin en iyi seçenek olduğunu veya küçük işin mutlaka büyüyeceğini göstermiyor."},{id:"M20",title:"NIMH · Ruh sağlığına özen göstermek",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Uzun süren ağır veya sıkıntı veren belirtiler, ilgi kaybı veya günlük işleri tamamlayamama uzman desteğini gerektirir. Acil tehlikede hemen yardım gerekir.",limitation:"Bu, halka yönelik bir rehber. ODA’nın etkisini sınayan bir deney değil; yalnızca isteksizliğe bakarak tanı koymaz. Kaygın varsa yardım istemek için iki haftanın geçmesini, art arda uygulama yapmayı veya dersleri bitirmeyi beklemen gerekmez."},{id:"motivation-sdt",title:"Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivasyon, yaptığın işten keyif almasan da benimsediğin değerleri yansıtabilir. Kuram, özerklik, yeterlik ve ilişki kurmayı temel ihtiyaçlar olarak önerir.",limitation:"Bu, bir kuramı ve araştırmaları anlatan derleme. ODA sorularını sınayan bir deney değil. Özerklik bağımsızlık demek değildir. Ödüller ve yükümlülükler hedefi kendiliğinden sana ait olmaktan çıkarmaz."},{id:"motivation-sdt-meta",title:"Ntoumanis ve diğerleri · 2021 · İhtiyaçları destekleyen sağlık programları",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 çalışmada, kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında mütevazı ortalama faydalar görüldü. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi.",limitation:"İncelenen sağlık programları birden çok desteği birleştiriyor. Çalışmalar arasında ciddi farklar var; araştırma tasarımları da sınırlı. Değerlerini düşünmeye yönelten tek bir soru bu programların yerini tutmaz. Bulgular her hedef için aynı etkiyi göstermiyor."},{id:"M16",title:"Fogg · Tiny Habits olumlu hareket önerisi",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg, küçük davranışın hemen ardından kişinin kendi seçtiği olumlu bir hareketi önerir.",limitation:"Bu, yöntemi öneren kişinin sayfası; kontrollü bir etki tahmini sunmuyor. Kutlamanın şart olduğu, sinirsel bağlantıları daha hızlı kurduğu veya kutu işaretlemenin aynı etkiyi verdiği bağımsız araştırmayla gösterilmedi."}],i=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"tr",title:"İşi sevmiyor musun? Hedefine bir bak.",goal:"Bu hedefin ayıracağın emeğe değip değmediğine karar ver. Sonra ona hizmet eden küçük bir işi dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Listedeki hedef sana pahalıya mı geliyor? Bu hafta vereceğin emeğin hayatında neyi değiştireceğine bak.",reason:{id:"motivation-1-reason",label:"Bu hedef hayatında neyi değiştirecek? Haftada ayıracağın zamana değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Ailem için yeni seçenekler yaratmak","Merakıma zaman ayırmak","Benimsediğim bir sorumluluğu yerine getirmek"]},why:{id:"motivation-1-why",label:"Bu hedef hayatında neyi değiştirecek? Haftada ayıracağın zamana değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir işi sevmemen, onun senin için önemsiz olduğu anlamına gelmez. Düzenli gelir için çalışmak, ailene bakmak veya bir meslek belgesi almak senin seçimin olabilir. İşi severek yapmak başka, neden yaptığını benimsemek başka. Başkalarının seni takdir etmesi de bu hedefi tek başına senin seçimin olmaktan çıkarmaz. İkisi aynı anda hayatında yer alabilir.","Hedef günlük hayatında neyi değiştirecek? Bu hafta ne kadar zamanını ya da enerjini alacak? Sürdürmeye, biçimini değiştirmeye, ertelemeye veya bırakmaya karar ver. Sürdüreceksen uygun bir anda işe yarayan küçük bir parçasını dene. Burada seçimini sınıyorsun. Gerçek niyetini ortaya çıkaran bir kişilik testi çözmüyorsun."],example:{title:"Leyla’nın ilk sorusu",text:"Saat 19.00’da Leyla iki seçeneği tartıyor: meslek belgesi için çalışmak veya ailesiyle zaman geçirmek. Dersleri sevmiyor ama belgenin açabileceği iş seçenekleri ona değerli geliyor. Hedefinden vazgeçmiyor ve mutfak masasında bir deneme sorusunu cevaplıyor. Cevabı eksik kalıyor. Denemesini kaydedip başka bir uygun an seçiyor. Çalışmaktan zevk aldığını söylemesine gerek duymuyor."}},move:{invitation:"Hedefini seç. Örneği kullanmadan önce, o hedef için ne yapacağını açıkça yaz.",instructions:["Örnekleri kendine göre düzenle. Bakım vermeyi, işi, ilişkileri veya kendi seçtiğin bir adımı düşünebilirsin.","Bu küçük işi ne zaman, neyin ardından ve nerede yapacağını planına yaz."],prompts:[{id:"motivation-1-0",label:"Bu hedefe zaman ayırınca başka neye daha az zaman kalacak?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla","Yarın çocuğu okuldan alma saatini Merve’yle netleştir","Müşteriye yazacağım bilgi notuna bir cümle ekle","Akşam konuşmamızda Serkan’a kararlaştırdığımız soruyu sor"],minimum:["Seçtiğim deneme sorusunu cevapla","Merve’ye okuldan alma saatini mesajla bildir","Bilgi notuna işe yarayan ilk cümleyi yaz","Serkan’a bugünkü randevusunun nasıl geçtiğini sor"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","Merve’nin okuldan alma saatiyle ilgili mesajı gelince","İşte saat 14.00 molam bittikten hemen sonra","Kararlaştırdığımız akşam konuşması başlayınca"],place:["Evde mutfak masasının başında","Mevcut mesajlaşmamızda","İşteki bilgisayarımın başında","Her zamanki telefon görüşmemizde"],minutes:[2,1,5],fallback:["Aynı notlardan daha kısa bir soruyu cevapla","Kararlaştırdığımız iletişim yoluyla aramayı dene","Cümleyi kullanabildiğim not aracına sesle yazdır","Kararlaştırdığımız mesajlaşma seçeneğini öner"],observation:["Yazdığım cevap ve harcadığım süre","Saati bildirdim mi? Yanıtı ayrı kaydet.","Bilgi notuna hangi işe yarar cümle eklendi","Sorduğum soru; yanıt gelmediyse bunu da yaz"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla",minimum:"Seçtiğim deneme sorusunu cevapla",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Aynı notlardan daha kısa bir soruyu cevapla",observation:"Yazdığım cevap ve harcadığım süre",minutes:2},{action:"Yarın çocuğu okuldan alma saatini Merve’yle netleştir",minimum:"Merve’ye okuldan alma saatini mesajla bildir",cue:"Merve’nin okuldan alma saatiyle ilgili mesajı gelince",place:"Mevcut mesajlaşmamızda",fallback:"Kararlaştırdığımız iletişim yoluyla aramayı dene",observation:"Saati bildirdim mi? Yanıtı ayrı kaydet.",minutes:1},{action:"Müşteriye yazacağım bilgi notuna bir cümle ekle",minimum:"Bilgi notuna işe yarayan ilk cümleyi yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Cümleyi kullanabildiğim not aracına sesle yazdır",observation:"Bilgi notuna hangi işe yarar cümle eklendi",minutes:5},{action:"Akşam konuşmamızda Serkan’a kararlaştırdığımız soruyu sor",minimum:"Serkan’a bugünkü randevusunun nasıl geçtiğini sor",cue:"Kararlaştırdığımız akşam konuşması başlayınca",place:"Her zamanki telefon görüşmemizde",fallback:"Kararlaştırdığımız mesajlaşma seçeneğini öner",observation:"Sorduğum soru; yanıt gelmediyse bunu da yaz",minutes:2}]},suggested:{action:"Örnek: meslek sınavımdaki ilk deneme sorusunu cevapla",minimum:"Seçtiğim deneme sorusunu cevapla",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: bugünkü soru aileme ayırdığım zamana denk geliyor",fallbackHint:"Aynı notlardan daha kısa bir soruyu cevapla",observationHint:"Yazdığım cevap ve harcadığım süre"},stopRule:"Hastayken, tehlike içindeyken veya günlük işlerini uzun süredir yapmakta zorlanırken kendini zorlama. Şimdi destek alabilirsin.",accessibleAlternative:"Ses kaydı, sesle yazma, yardımcı araçlar veya kararlaştırılmış yardım kullan. Açıkça ara vermeyi de seçebilirsin."},result:{question:"Seçtiğin davranışı gerçekten denedin mi?",observationPrompt:"Gerçekte ne yaptın, buna ne kadar zaman veya enerji harcadın?"},judgment:{primary:{id:"motivation-1-decision",scenario:"Leyla meslek belgesi için çalışmayı sevmiyor. Ailesi için daha düzenli iş seçenekleri istiyor. İş arkadaşları da bu belgeyi değerli buluyor.",question:"Bu hedefi sürdürüp sürdürmeyeceğini nasıl sınayabilir?",options:[{id:"motivation-1-endorse",text:"Getireceği faydayı ve istediği zamanı kabul edip etmediğine baksın, sonra bir deneme sorusunu cevaplasın.",feedback:"Bu seçim, işi sevmemekle hedefi benimsememeyi ayırıyor ve yapılabilir bir davranışı sınıyor. Takdir görmekle kendi nedenin bir arada olabilir. Zamanı uymuyorsa hedefi değiştirmek veya ertelemek hâlâ Leyla’nın seçimi."},{id:"motivation-1-interest",text:"Bu belgenin hâlâ kendi hedefi olup olmadığına karar vermeden önce bir hafta daha keyifli bir hedef denesin.",feedback:"Başka bir ilgi alanını denemek yararlı olabilir. Ama keyif almak, bu hedefin Leyla’ya ait olup olmadığını tek başına söylemez. Önce benimsediği faydaya ve vereceği zamana baksın. Değerli bir iş sıkıcı kalabilir."},{id:"motivation-1-advice",text:"Belgeli iş arkadaşlarına hangi eğitimi seçeceklerini sorsun, sonra onların önerdiği meslek belgesi için çalışsın.",feedback:"İş arkadaşları seçenekleri ve gerekenleri açıklayabilir. Ama Leyla’nın neye zaman ayıracağına onun yerine karar veremezler. Öneriyi benimsemeden önce kendi nedenini ve gerçekten ayırabileceği zamanı netleştirmesi gerekir."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"Seçtiğin hedef zor olabilir. Değerine ve alacağı emeğe bak, sonra küçük bir parçasını dene.",followUp:{questionId:"motivation-1-return",question:"Denediğin iş seçtiğin nedene hizmet etti mi? Aldığı zaman ve enerji hâlâ buna değer mi?",observationPrompt:"Gerçekte ne yaptın, ne kadar zaman veya enerji harcadın?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Benimsemek, zevk almak zorunda olmak değildir",paragraphs:["Ryan ve Deci’nin öz belirleme kuramı, bir işi içinden gelerek sevmekle o işin nedenini benimsemeyi ayırır. Dışarıdan gelen bir hedefi zamanla değerli bulabilirsin. Meslek belgesi, gelir, bakım veya ortak bir sorumluluk, yapılan iş sıkıcı olsa da senin için önemli olabilir. Buradaki özerklik, hiçbir yükümlülüğün veya dış etki olmaması değil, seçim yapabildiğini hissetmektir. 2000 tarihli yazıları bir kuram ve anlatı derlemesidir. Bu dersin sınandığı bir deney değildir. [M01]","Bu dersteki sürdür, değiştir, ertele veya bırak seçimi ODA’nın düşünme alıştırmasıdır. Saf niyetleri ortaya çıkarmaz, bir hedefin gerçekten sana ait olduğunu onaylamaz. Cerasoli ve çalışma arkadaşlarının büyük meta-analizinde, içten gelen motivasyon da teşvikler de performansla ilişkiliydi. İşin niteliği ve miktarı için ilişki farklıydı. Sonuçlar ödüllerin her koşulda iyi ya da kötü olduğunu söylemiyor. [M04] Birden çok nedenin olduğunu kabul edebilirsin. Yine de bu davranışın istediğin hayata hizmet edip etmediğine kendin karar verebilirsin."]},{heading:"Tek bir soru, bütün programın yerini tutmaz",paragraphs:["Ntoumanis ve çalışma arkadaşları, öz belirleme kuramından yararlanan 73 sağlık müdahalesi çalışmasını birleştirdi. Kişinin benimsediği motivasyonda ve sonraki sağlık davranışlarında ortalama olarak mütevazı faydalar buldular. Programlarda birden çok destek vardı; sonuçlar ciddi ölçüde farklılaşıyordu. Hemen sonraki fiziksel sağlık gelişimi istatistiksel olarak anlamlı değildi. Bu sonuçlar her meslek, eğitim veya kişisel hedef için aynı faydayı göstermiyor. [M02]","Nedenini soran tek bir cümle o programların yerini tutamaz. Burada nedenin sana küçük bir denemede yol gösteriyor: bir hedef, gerçekten yapılan bir iş, dürüst bir kayıt ve sonraki uygun an. İlk denemede heves şartı koymadan uygunluğa, erişime ve harcadığın emeğe bak. İstersen ayrıntıları kendine sakla. Sonraki derslerde aynı yönü koruyup işe yarayan küçük bir adımı, kullanılabilir bir başlama işaretini ve gerçek bir engele vereceğin yanıtı sınayacaksın. Hedefini veya koşullarını yeniden değerlendirmen gerekiyorsa ara vermek ya da destek istemek de geçerli bir seçimdir."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"tr",title:"Kitabı yine açıp okumadan kapattın mı?",goal:"Seçtiğin işin küçük bir kısmını dene. Küçük olsun ama yine de işine yarasın.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kitabı açtın ama okumadın mı? İşe yarayan kısmı bugün yapabileceğin kadar küçült.",reason:{id:"motivation-2-useful-unit-cost",label:"İşe yarayan kısma yer açmak için hangi hazırlığı bırakabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Tekrar açmayı bırak, bir cümle oku","Düzenlemeyi bırak, bir cümle yaz","İş kalsın, boyutu küçülsün"]},why:{id:"motivation-2-why",label:"Seçtiğin nedene hizmet eden en küçük yararlı iş ne?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin hedefi koru. Yapacağın işi bugüne sığacak kadar küçült. İşe yarayan kısmını koru. Kitabı elinin altına koy, sonra bir cümle oku. Başvuru dosyasını aç, sonra işe yarayan bir cümle yaz. Malzemeleri hazırlamak hazırlıktır. Okuduğun ya da yazdığın cümle ise denemek istediğin davranışın kendisidir. Birbirinin yerine geçmezler. İkisini ayrı ayrı kaydedebilirsin.","Alışkanlık araştırmaları, tekrarlanan koşullarda yapılan davranışlara bakar. Her küçük başlangıcın büyüyeceğini ya da kutucuğu işaretlemenin kutlamayla aynı etkiyi yaratacağını göstermez. En küçük adımın küçük kalabilir. Bir kez dene, gerçekte ne olduğunu kaydet. Sonra bu miktarın seçtiğin nedene hâlâ hizmet edip etmediğine bak."],example:{title:"Leyla’nın daha küçük sorusu",text:"Salı akşamı yemekten sonra Leyla’nın aynı meslek belgesi için iki dakikası var. Notlarını elinin altına koyuyor, sonra kısa bir deneme sorusunu cevaplıyor. Ailesine ayırdığı zaman da önemli olduğu için orada duruyor. Cevabı düzeltme istiyor. Süreyi uzatmadan, yazdığı cevabı çalışma olarak kaydediyor. Notları önüne koymasını ise ayrı bir hazırlık olarak tutuyor."}},move:{invitation:"Aynı işi sürdür. Planını kaydetmeden önce işe yarayan en küçük kısmını seç.",instructions:["İşi ve yapabildiğin ortamı değiştirme. Yalnızca ne kadarını yapacağını yeniden seç.","Gereken malzemeyi elinin altına koy, sonra o küçük işi gerçekten yap."],prompts:[],suggestions:{action:["Örnek: meslek sınavımdaki sıradaki soruyu cevapla","Kaydettiğim başvuru metninin o paragrafını yaz","Üzerime aldığım mutfak temizliğini yap"],minimum:["O sorunun ilk bölümüne bir cevap yaz","O paragrafa işe yarayan bir cümle yaz","Kararlaştırdığımız iki kupayı yıka"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","İşte saat 14.00 molam bittikten hemen sonra","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Evde mutfak masasının başında","İşteki bilgisayarımın başında","Kullanabildiğim mutfak lavabosunda"],minutes:[2,1],fallback:["Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır","Notlarıma işe yarayan bir cümleyi sesle yazdır","Kararlaştırdığımız, yapabileceğim başka bir temizlik işini seç"],observation:["Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı","Cümle yazıldı mı, yalnızca dosya mı açıldı","İş yapıldı mı, yalnızca malzemeler mi dizildi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: meslek sınavımdaki sıradaki soruyu cevapla",minimum:"O sorunun ilk bölümüne bir cevap yaz",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır",observation:"Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı",minutes:2},{action:"Kaydettiğim başvuru metninin o paragrafını yaz",minimum:"O paragrafa işe yarayan bir cümle yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Notlarıma işe yarayan bir cümleyi sesle yazdır",observation:"Cümle yazıldı mı, yalnızca dosya mı açıldı",minutes:1},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Kararlaştırdığımız iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Kararlaştırdığımız, yapabileceğim başka bir temizlik işini seç",observation:"İş yapıldı mı, yalnızca malzemeler mi dizildi",minutes:2}]},suggested:{action:"Örnek: meslek sınavımdaki sıradaki soruyu cevapla",minimum:"O sorunun ilk bölümüne bir cevap yaz",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: malzemeleri hazırlıyorum ama soruyu cevaplamıyorum",fallbackHint:"Kullanabildiğim notlardan ilk bölümün cevabını sesle yazdır",observationHint:"Cevap yazıldı mı, yalnızca malzemeler mi hazırlandı"},stopRule:"Güvenli bir iş seç. Ağrı, hastalık, acil ihtiyaç veya kullanamadığın bir ortam varsa dur.",accessibleAlternative:"Dinle, sesle yazdır veya yardımcı araç kullan. Hazırlık seçersen bunu açıkça belirt; hazırladığını kullanmak için sonraki uygun zamanı seç."},result:{question:"En küçük adımının işe yarayan kısmını yaptın mı?",observationPrompt:"Gerçekten yapılan iş neydi, yalnızca hazırlık olan neydi?"},judgment:{primary:{id:"motivation-2-decision",scenario:"Bir başvuru yazmak istiyorsun. Üç oturumdur dosyayı açtın ama hiçbir şey yazmadın. İki dakikan var ve istenen bölümün içeriğini biliyorsun.",question:"Şimdi hangi küçük adım yararlı ilerlemeyi sınar?",options:[{id:"motivation-2-bigger",text:"Daha sonra uzun bir zaman ayır, böylece tam bir cevap yazmaya başlamak daha anlamlı gelsin.",feedback:"Daha uzun süre bitirmeye yardımcı olabilir. Ama şu anki yalnızca hazırlık yapma döngüsünü sınamıyor. Şimdi taslak bir cümle yaz; daha uzun zamana ihtiyacın olup olmadığına sonra karar ver."},{id:"motivation-2-outline",text:"Bu iki dakikada üç maddelik bir taslak çıkar, sonra istenen bölümü daha uzun bir zamanda yaz.",feedback:"Taslak içeriği netleştirebilir. Ama bu bölümü zaten biliyorsun; tekrar eden engel, metni yazmaya başlamak. Taslak bir cümle o engeli şimdi sınar. Taslak çıkarırsan onu hazırlık olarak kaydet."},{id:"motivation-2-sentence",text:"İstenen bölüme taslak bir cümle yaz, sonra elindeki iki dakikalık süre dolunca dur.",feedback:"Bu seçim davranışın kendisini içeriyor ve düzenleyebileceğin bir parça bırakıyor. Başvurunun başarısını garanti etmiyor, daha uzun süre de istemiyor. Yazdığın cümleyi dosyayı açmaktan ayrı kaydet."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Başlangıcı bugün yapılabilir hale getir. Küçültürken asıl işe yarayan kısmı içinden çıkarma.",followUp:{questionId:"motivation-2-return",question:"Küçülttüğün işi gerçekten yaptın mı, yoksa sadece hazırlık mı yaptın?",observationPrompt:"Gerçekten yapılan iş neydi, yalnızca hazırlık olan neydi?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Küçük olması bir seçimdir, garanti değil",paragraphs:["Wood ve Rünger alışkanlıkları, tekrarlanan koşullarla bağlantılı öğrenilmiş davranışlar olarak ele alıyor. Tekrar, davranışın daha kendiliğinden yapılmasını destekleyebilir; bilinçli hedefler de önemini koruyabilir. Derlemeleri tek cümlenin en iyi miktar olduğunu veya her küçük davranışın mutlaka büyüyeceğini göstermiyor. Bu derste küçük bir iş seçiyorsun. Bu haftaki koşullarında onu yapabiliyor musun ve işine yarıyor mu, buna bakıyorsun. [M07]","Seçtiğin küçük adımda hazırlığı, yapmak istediğin işten ayır. Cevaplanan bir soruyu kontrol edebilirsin. Okunan bir cümle bilgi verebilir. Yazılan bir cümleyi düzenleyebilirsin. Malzemelerin hazır olması yararlı bir hazırlıktır ama bu davranışların kendisini içermez. Birkaç küçük deneme seçtiğin nedene hiç hizmet etmiyorsa davranışına veya hedefine yeniden bak. Farklı bir parça, daha fazla destek ya da gerçekten ayırabildiğin daha uzun bir zaman gerekebilir. Kolayca bir kutuyu işaretleyebiliyor olman, yapılmamış işi ilerleme sayman için bir neden değildir. [M07]"]},{heading:"Uygulayıcının tarifi de sınırlıdır",paragraphs:["BJ Fogg’un Tiny Habits tarifi, mevcut bir günlük rutini çok küçük bir davranışla eşleştirir. İşlemeyen eşleşmeyi yeniden düzenlemeyi önerir. Bu bir uygulayıcı tekniğidir. İncelenen sayfa, tarifin tamamının sıradan başlama işareti planından daha iyi olduğunu bağımsız biçimde göstermiyor. Her davranışın bir dakikadan kısa sürmesi gerektiğini de kanıtlamıyor. [M15]","Fogg, küçük davranışın hemen ardından kişinin kendi seçtiği olumlu bir hareketi de önerir. Sinirsel bağlantıların daha hızlı kurulması, kutlamanın şart olması veya kutuyu işaretlemenin aynı pekiştirme işini yapması iddiaları, araştırma dosyasında kontrollü kanıtla doğrulanmadı. [M16] Memnuniyet gelirse fark edebilirsin; gelmiyorsa üretmeye çalışma. Ne yaptığını dürüstçe yaz. Sonrasında ne hissettiğin ayrı bir bilgidir. İşe yarayan en küçük adımda durabilir, yarın aynı boyutta tutabilir, araçlarını veya erişim biçimini değiştirebilirsin. Daha az iş yapmak, karakterinin daha zayıf olduğunu göstermez."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"tr",title:"Hatırlatıcı çaldı. Yine başlayamadın.",goal:"Seçtiğin küçük işi, zamanın, malzemen ve erişimin olduğu bir başlama anında dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hatırlatıcı sen hâlâ otobüsteyken mi çalıyor? İşi gerçekten yapabileceğin uygun bir başlama anı seç.",reason:{id:"motivation-3-available-setting-cost",label:"Hangi uygun ortamı kullanacaksın? Ona yer açmak için neyi başka zamana alacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Koruyabildiğim sabit molayı kullanmak","Esnek bir ev işini başka zamana almak","Çalışırken bakımın aksamamasını sağlamak"]},why:{id:"motivation-3-why",label:"Hedefine gerçekten zaman ayırabileceğin hangi an var?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlama işaretinin üç şartı var: o anın gelmesi, senin fark etmen ve o işi yapabiliyor olman. Çocuğu okula bıraktıktan sonra doğrudan işe gidiyorsan, o an masa başında çalışmaya uygun değildir. İşe yarayan küçük adımını koru. Onu gerçekten yapmana izin veren bir ortam seç. Zaman var gibi görünmesi, malzemenin de yanında olduğu anlamına gelmez.","“Şu olunca bunu yapacağım” gibi belirli planlar, niyetini davranışa dönüştürmene yardımcı olabilir. Tekrarlanan koşullarda davranışı yinelemek alışkanlığı destekleyebilir. Ama herkes için aynı bitiş tarihi yok. Bugün otomatikleşmeye çalışmak yerine başlama anını sına. Bu üç koşuldan hangisi tuttu, hangisini değiştirmen gerekiyor, kaydet."],example:{title:"Leyla’nın uygun çalışma anı",text:"Leyla sorusunu çocuğu okula bıraktıktan sonra cevaplamayı planlamıştı. Ama notları yanında olmadan doğrudan işe gitti. Çarşamba günü aynı soruyu akşam yemeğinden sonraya, mutfak masasına aldı. Başlama anı geldi ve Leyla fark etti. Masayı toplamadan soruyu cevapladı. Artık üzerinde çalışabileceği bir cevabı var. Önceki uygun olmayan anı da kayıtta bıraktı; hiç yaşanmamış gibi silmedi."}},move:{invitation:"Aynı küçük işi sürdür. Başlayabileceğin bir an ve yapabileceğin bir yer seç.",instructions:["Seçtiğin an geliyor mu? Fark ediyor musun? Planındaki işi o anda yapabiliyor musun?","Tarihi seç. Malzemenin veya gerekli erişimin o anda orada olacağını kontrol et."],prompts:[],suggestions:{action:["Örnek: kaydettiğim meslek sınavı sorusunu cevapla","Kaydettiğim başvuru metnine o cümleyi yaz","Üzerime aldığım mutfak temizliğini yap"],minimum:["Aynı deneme sorusuna bir cevap yaz","Aynı işe yarayan cümleyi yaz","Üzerime aldığım aynı iki kupayı yıka"],cue:["Akşam yemeğinde kendi tabağımı kaldırdıktan sonra","Sabit 12.30 molam başlayınca","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Evde mutfak masasının başında","Molada kullanabildiğim masada","Kullanabildiğim mutfak lavabosunda"],minutes:[2,1],fallback:["Yarın yemek sonrası kullanabildiğim notlardan soruya dön","Kaydettiğim notlardan o cümleyi sesle yazdır","Yardımın kararlaştırıldığı bir sonraki temizlik saatini kullan"],observation:["An geldi mi? Fark ettim mi? Yapabildim mi?","Bu ortam aynı küçük işi yapmaya uygun muydu","Başlama anı geldi mi, üstlendiğim iş yapılabilir miydi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",place:"Evde mutfak masasının başında",fallback:"Yarın yemek sonrası kullanabildiğim notlardan soruya dön",observation:"An geldi mi? Fark ettim mi? Yapabildim mi?",minutes:2},{action:"Kaydettiğim başvuru metnine o cümleyi yaz",minimum:"Aynı işe yarayan cümleyi yaz",cue:"Sabit 12.30 molam başlayınca",place:"Molada kullanabildiğim masada",fallback:"Kaydettiğim notlardan o cümleyi sesle yazdır",observation:"Bu ortam aynı küçük işi yapmaya uygun muydu",minutes:1},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Üzerime aldığım aynı iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Yardımın kararlaştırıldığı bir sonraki temizlik saatini kullan",observation:"Başlama anı geldi mi, üstlendiğim iş yapılabilir miydi",minutes:2}]},suggested:{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",minutes:2,cueHint:"Akşam yemeğinde kendi tabağımı kaldırdıktan sonra",placeHint:"Evde mutfak masasının başında",obstacleHint:"Örnek: önceki başlama anında notlarım yanımda değildi",fallbackHint:"Yarın yemek sonrası kullanabildiğim notlardan soruya dön",observationHint:"An geldi mi? Fark ettim mi? Yapabildim mi?"},stopRule:"Araç kullanırken ya da bakım işini veya güvenliği aksatacak bir yerde uygulama yapma.",accessibleAlternative:"Görebildiğin veya kullanabildiğin hatırlatıcı, sesli malzeme, kararlaştırılmış yardım veya daha uygun bir sonraki anı kullan."},result:{question:"Başlama anında o küçük işi gerçekten yapabildin mi?",observationPrompt:"Başlama anı geldi mi, fark ettin mi, işi yapabildin mi?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Leyla bugün planındaki soruyu cevaplamak istiyor. Çocuğu okula bıraktıktan sonra doğrudan işe gittiği için önceki plan işlemedi. Akşam, notları elinin altındayken ayırabileceği beş dakika var. Sabit öğle molasında notlarının telefon kopyasını kullanabilir. Yarın trende de çalışabilir ama kalkış saati henüz belli değil.",question:"Aynı küçük işi bugün denemesi için hangi değişiklik en uygun?",options:[{id:"motivation-3-dinner",text:"Akşam yemeği sonrası ayırabildiği zamanı kullansın; elindeki notlarla planındaki aynı soruya bir cevap yazsın.",feedback:"Bu seçim işi ve malzemeyi koruyup uygun olmayan başlama anını değiştiriyor. Bugünkü zaman kesinleşmiş. O an geldi mi, Leyla fark etti mi, soruyu cevaplayabildi mi? Bunları kaydet."},{id:"motivation-3-phone-copy",text:"Öğle molasında notlarının telefon kopyasını hazırlasın, soruyu daha sonraki uygun bir molada cevaplasın.",feedback:"Taşınabilir notlar ileride iş molalarında yardımcı olabilir. Ama bu seçim bugünkü bilinen zamanı hazırlığa ayırıyor; cevaplamanın tarihi belirsiz kalıyor. Akşam elindeki notlarla kayıtlı davranışı bugün sınayabilir."},{id:"motivation-3-train",text:"Notlarını yarınki tren için yanına alsın, kalkış kesinleşince kaydettiği aynı soruyu trende cevaplasın.",feedback:"Tren, saati kesinleşince uygun bir ortam olabilir. Ama bugün uygun zaman varken denemeyi erteliyor. Akşam artık uygun gelmezse trene göre plan kaydetmeden önce yolculuk tarihini ve saatini netleştirsin."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"Seçtiğin başlama anı gelmeli. O anı fark etmeli ve işi yapabilecek durumda olmalısın.",followUp:{questionId:"motivation-3-return",question:"Başlama anı gelmedi mi, fark etmedin mi, yoksa o anda işi yapamadın mı?",observationPrompt:"Başlama anı geldi mi, fark ettin mi, işi yapabildin mi?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Başlama işareti, sınayacağın bir koşuldur",paragraphs:["Gollwitzer ve Sheeran’ın 2006 tarihli derlemesi, bir durumu seçilmiş bir davranışa bağlayan planların 94 bağımsız sınamasını birleştirdi. Hedefe ulaşma ortalama olarak arttı. Geçmiş çalışmalardaki standartlaştırılmış etki büyüklüğü 0,65’ti. Bu, yüzde 65 gelişme demek değildir. Uygulamadaki hatırlatıcının etkisini de öngörmez. Bu ortalamalar farklı hedeflerden ve ortamlardan geliyor. Burada seçtiğin çalışma anının etkisi ayrıca ölçülmüş değil. [M08]","Wood ve Rünger, aynı ortamla bağlantılı tekrarı alışkanlık öğrenmenin bir parçası olarak anlatır. Tek başına bir işaret davranışı garanti etmez; her günlük rutin de otomatik olmak zorunda değildir. [M07] ODA’nın “geldi, fark edildi, yapılabildi” kontrolü bir öğretme aracıdır. Kaçırılan hatırlatıcıyı, eksik malzemeden veya başka bir sorumluluktan ayırmana yardım eder. Seçtiğin an gelmediyse uygun olduğu durumda “Fırsat olmadı” seçeneğini kullan. Geldiyse ama yapmadıysan da bunu açıkça yazabilirsin. Bu olayı, ne kadar kararlı olduğuna dair genel bir yargıya çevirmene gerek yok."]},{heading:"Altmış altı gün bir model tahminiydi",paragraphs:["Lally’nin 2010 çalışması, kişilerin seçtiği günlük davranışları 84 gün izledi. Verilere iyi uyan 39 otomatikleşme eğrisinde, son düzeyin yüzde 95’ine ulaşmak için modelin tahmin ettiği ortanca süre 66 gündü. Tahminler 18 ile 254 gün arasındaydı. En uzun tahmin, gözlem süresinin dışına uzanıyordu. Bunlar gözlenmiş en hızlı, ortalama ve en yavaş alışkanlık tamamlama tarihleri değildi. [M05]","Meslek sınavına çalışman, araştırmadaki yeme, içme veya hareket davranışlarının aynısı değil. Tahmini kendine son tarih yapmak veya çalışmanın artık zahmetsiz olması gerektiğine kanıt saymak doğru olmaz. Aynı denemeyi sürdür. Gerçekten uygun anlara, işe yarayan davranışa ve onu destekleyen koşullara bak. Bir başlama anı hafta içi uyarken vardiya veya bakım günlerinde başka düzen gerekebilir. Seçerek tek bir değişikliği dene. Önceki kaydı da koru ki geri baktığında hayali bir düzene değil, gerçekte karşılaştığın koşullara bakabilesin."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"tr",title:"Planın bozulduğu anı da hesaba kat",goal:"Karşılaştığın bir engel için yapabileceğin tek bir adımı dene. İhtiyaçlarını ve sorumluluklarını aksatma.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Çalışma saatin çocuğu yatırmaya mı denk geliyor? Kendine gaz vermek bakım işini üstlenecek birini getirmez.",reason:{id:"motivation-4-accepted-change-cost",label:"Kaydındaki engeli gidermek için hangi somut değişikliği kabul edeceksin?",kind:"text",maxLength:160,optional:!0,suggestions:["Saati değiştir, işe yarayan küçük iş kalsın","Yardımı kesinleşmiş saymadan önce açıkça yardım iste","Daha çok zorlamak yerine erişim biçimini değiştir"]},why:{id:"motivation-4-why",label:"Bu hedef ilerlerken hangi gerçek ihtiyacın korunması gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hedefini ve işe yarayan küçük işini koru. Gerçek bir denemeden tek bir engel seç: başka işe kaymak, eksik malzeme, bakım sorumluluğu veya sağlık ihtiyacı. İstenen sonucu, engeli ve o engelde yapacağını birlikte planlamak araştırmalarda ortalama olarak mütevazı faydalar gösteriyor. Ama olmayan zamanı veya yardımı var edemez. Karşılaştığın koşulu açıkça adlandır; hepsini isteksizlik diye açıklama.","Seçtiğin adım o engele uysun. Dikkatini dağıtan bir sekme için ortamı değiştirebilirsin. Bakım verdiğin kişi için, o sırada başka birinin sorumluluğu üstlenmesi gerekebilir. Hastalıkta dinlenmek gerekebilir. O adımla yapabileceğin ilk yararlı işi planla, sonra uygun anda sına. Prova hazırlıktır; yedek planın gerçekten işlediğinin kanıtı değildir."],example:{title:"Leyla’nın bakım yardımı",text:"Perşembe günü Leyla’nın çalışma anı, çocuğunu yatırdığı sırada geliyor. Eşi, yatma hazırlığı bitince beş dakika çocukla ilgilenmeyi kabul ediyor. Leyla aynı soruyu o zamana alıyor. Çocuğun bakımı sürerken masada soruyu cevaplıyor. Yardımı ve cevabını ayrı kaydediyor. Soru hâlâ çalışma istiyor. Bugünkü anlaşmaya bakıp yarın da aynı yardımın hazır olacağını varsaymıyor."}},move:{invitation:"Kaydındaki engele uyan tek bir koşulu değiştir. İşe yarayan davranışın aynı kalsın.",instructions:["Bakım yardımı kesinleştiyse kayıtlı işini dene. Yalnızca kaydındaki engelle ilgili koşulu değiştir.","Anlaşma yoksa “Bunu uyarla”, ardından “Destek” seç. Belli iş, kişi ve zaman için yardım iste.","Kabul edilmezse gerçekten uygun bir zaman seç veya ara ver. Yardım istemek uygulamadan ayrı."],prompts:[{id:"motivation-4-support-request",label:"Destek gerekiyorsa hangi iş için, kimden, ne zamana yardım isteyeceksin?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Örnek: Merve’ye mesaj atıp beş dakikalık bakım yardımı iste."}],suggestions:{action:["Örnek: kaydettiğim başvuru metninin o cümlesini yaz","Bakım yardımı kararlaştırıldığında kayıtlı sorumu cevapla","Kaydettiğim bölümü sesli kayıttan dinle"],minimum:["Başvurudaki aynı işe yarayan cümleyi yaz","Aynı deneme sorusuna bir cevap yaz","Aynı işe yarayan bölümü dinle"],cue:["İşte saat 14.00 molam bittikten hemen sonra","Kararlaştırdığımız beş dakikalık bakım yardımı başlayınca","Kesinleşen 12.30 molam başlayınca"],place:["İşteki bilgisayarımın başında","Evde mutfak masasının başında","Rahatça kullanabildiğim sessiz mola alanında"],minutes:[2,5],fallback:["Gereksiz bildirimleri sessize al; acil iletişimi açık tut","Bakım yardımı olmazsa çalışmaya ara ver","Ses kaydı çalışmazsa kullanabileceğim başka biçimini iste"],observation:["Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı","Bakım desteğini ve soruya verdiğim cevabı ayrı kaydet","Bölüme erişebildim mi? Dinledim mi? Ayrı kaydet."],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim başvuru metninin o cümlesini yaz",minimum:"Başvurudaki aynı işe yarayan cümleyi yaz",cue:"İşte saat 14.00 molam bittikten hemen sonra",place:"İşteki bilgisayarımın başında",fallback:"Gereksiz bildirimleri sessize al; acil iletişimi açık tut",observation:"Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı",minutes:2},{action:"Bakım yardımı kararlaştırıldığında kayıtlı sorumu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Kararlaştırdığımız beş dakikalık bakım yardımı başlayınca",place:"Evde mutfak masasının başında",fallback:"Bakım yardımı olmazsa çalışmaya ara ver",observation:"Bakım desteğini ve soruya verdiğim cevabı ayrı kaydet",minutes:2},{action:"Kaydettiğim bölümü sesli kayıttan dinle",minimum:"Aynı işe yarayan bölümü dinle",cue:"Kesinleşen 12.30 molam başlayınca",place:"Rahatça kullanabildiğim sessiz mola alanında",fallback:"Ses kaydı çalışmazsa kullanabileceğim başka biçimini iste",observation:"Bölüme erişebildim mi? Dinledim mi? Ayrı kaydet.",minutes:5}]},suggested:{action:"Örnek: kaydettiğim başvuru metninin o cümlesini yaz",minimum:"Başvurudaki aynı işe yarayan cümleyi yaz",minutes:2,cueHint:"İşte saat 14.00 molam bittikten hemen sonra",placeHint:"İşteki bilgisayarımın başında",obstacleHint:"Örnek: gereksiz telefon bildirimleri son cümlemi böldü",fallbackHint:"Gereksiz bildirimleri sessize al; acil iletişimi açık tut",observationHint:"Bildirim geldi mi; seçtiğim yanıt yazmaya yaradı mı"},stopRule:"Bakımı ve acil ihtiyaçları aksatma. Hastalıkta veya güvenli olmayan koşullarda destek ya da dinlenmeyi seç.",accessibleAlternative:"Kararlaştırılmış yardım iste, erişimi veya zamanı değiştir. Destek istemek ya da dinlenmek de seçebileceğin bir adım."},result:{question:"Seçtiğin çözüm sayesinde planındaki küçük işini yapabildin mi?",observationPrompt:"Engel çıktı mı, çıktığında hangi yanıtı kullandın?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Gitar çalışması çocuğun yatma hazırlığına denk geliyor. Bu akşam için beş dakikalık bakım yardımı kesinleşmiş, gitar hazır. Komşu cumartesi daha uzun yardım edebilir ama anlaşmadılar. Ebeveyn, bakımı aksatmadan bu akşam kısa bir bölüm çalmak istiyor.",question:"Sıradaki denemeye en uygun yanıt hangisi?",options:[{id:"motivation-4-confirmed-cover",text:"Bu akşam kesinleşen beş dakikalık bakım yardımı sırasında kısa bölümü çalsın, yardım süresi bitince dursun.",feedback:"Anlaşma, işi büyütmeden eksik koşulu sağlıyor. Aynı kısa bölümü dene; çalışmayı bakım yardımından ayrı kaydet. Bu akşamki düzen, gelecekteki yardımın da şimdiden kararlaştırıldığı anlamına gelmez."},{id:"motivation-4-saturday-request",text:"Komşudan cumartesi daha uzun bakım yardımı istesin, o çalışmayı planlamadan önce yanıtın kesinleşmesini beklesin.",feedback:"Bu, ilerideki bir fırsat için güvenli bir destek isteği. Ama bu akşam zaten yapılabilir olan kısa bölümü sınamıyor. Bu akşam artık uymuyorsa seç; anlaşılana kadar cumartesiyi kesinleşmiş sayma."},{id:"motivation-4-prepare-first",text:"Bu akşam yardım aldığı beş dakikada akordu kontrol edip başka bir çalışma zamanı için bölümü işaretlesin.",feedback:"Gerektiğinde akordu kontrol etmek ve çalacağın bölümü işaretlemek yararlı bir hazırlıktır. Burada çalgı ve bölüm zaten hazır. Tekrar hazırlık yaparsan asıl çalışmayı denememiş olursun. Kesinleşen bakım desteği sayesinde ayırabildiğin zamanda o bölümü çal."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"Seçtiğin yanıt karşılaştığın engele uysun. İşe yararken gerçek ihtiyaçları ve sorumlulukları da korusun.",followUp:{questionId:"motivation-4-barrier-response-return",question:"Kaydettiğin iş gerçekten yapıldı mı? Değiştirdiğin koşul, kaydındaki engeli gidermeye yaradı mı?",observationPrompt:"Hangisi uygulamaydı, hangisi destekti? Hangi engel hâlâ vardı?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Planlama araştırması süreyi ve desteği de içerir",paragraphs:["Wang ve çalışma arkadaşlarının 2021 derlemesi, zihinsel karşılaştırmayı “şu olursa bunu yapacağım” planlarıyla birleştiren 21 makaledeki 24 etkiyi topladı. Hedefe ulaşmadaki ortalama etki küçük ile orta arasındaydı. Sonuçlar hedefe göre değişti; yayın yanlılığına işaret eden bulgular vardı. Sonucu, engeli ve yanıtı birleştirmek dilekleri garanti etmez. Düşüncelerin dış olayları değiştirdiğini ya da her WOOP biçiminin birbirine eşit olduğunu göstermez. [M10]","Duckworth ve çalışma arkadaşları bir okuldaki 77 beşinci sınıf öğrencisiyle akademik bir program denedi. Öğrenciler küçük gruplarda birer saatlik üç oturum yaptı. Alıştırmalar tekrarlandı, hatırlatma kartları kullanıldı. Bazı akademik sonuçlar iyileşti ama sonraki gruplar arası farklar anlamlı değildi. [M03] ODA’nın kısa yetişkin alıştırmasında katılımcı, destek ve süre farklı. Bu, sınanabilir bir yanıt seçmek için uyarlama; araştırmadaki programın bütünü değil. Faydalıysa prova yap. Sonra hazırlığı, engelin gerçekten çıktığı ve yanıta ihtiyaç duyduğun andan ayrı tut."]},{heading:"Engeli tanı, kendini suçlama",paragraphs:["Planlama yöntemi istenen sonuca, engele ve o engele karşı seçilen davranışa bakar. Her engelin senin tutumundan kaynaklandığını göstermez. Bakım, para, engellilikle ilgili erişim sorunları, vardiya, hastalık veya birinin zarar veren davranışı, neyi yapabileceğini sınırlayabilir. İşe yarayan yanıt kararlaştırılmış yardım, değişen saat, bir uyarlama, dinlenme veya sınır olabilir. Yetişkinler için uyarlamada bu koşulları dürüstçe adlandırmak gerekir. [M03, M10]","Tek bir koşulu değiştirmek için gerçekte olanı kaydettiğin yere bak. Başlama anı geldi ama malzeme yoksa daha güçlü söz vermek sorunu çözmez. Bakım verdiğin kişi sana ihtiyaç duyduysa, onun bakımını aksatmayacak bir düzen kur. Dikkatini dağıtan alışkanlık ortaya çıktıysa acil iletişimi açık bırakan bir yanıt dene. Hiç çıkmayan engelin yedek yanıtı da sınanmış sayılmaz. Küçük işi, yardım ayarlamaktan veya malzemeyi taşımaktan ayrı kaydet. Sonra işe yarayan düzeni koru. Yeni ritüeller biriktirmene veya daha istekli hissetmeyi şart koşmana gerek yok."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"tr",title:"Bir gün aksadı mı? Uygun bir zamanda dön.",goal:"Aynı denemeyi gözden geçir. İşe yarayan bir koşulu koru. Sıradaki denemeyi yapabileceğin bir tarih seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Denemeler aksadı mı? Hedefin mi değişti, yoksa ayırabildiğin zaman mı?",reason:{id:"motivation-5-reason",label:"Bu hedef gelecek hafta hâlâ zaman ayırmaya değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Hâlâ seçtiğim hedefe geri dönmek","Artık uymayan başlama anını değiştirmek","Dinlenmeyi koruyup gereken desteği istemek"]},why:{id:"motivation-5-why",label:"Bu hedef gelecek hafta hâlâ zaman ayırmaya değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin nedene, işe yarayan küçük adıma, başlama anına ve gerçek kayıtlarına bak. İlerlemeyi izlemek, araştırmalarda ortalama olarak hedefe ulaşmayı destekleyebilir. Ama denenmemiş planı yapılmış işe çeviremez. Kayıt boşsa başarısız oldun da diyemez. Neyin yardım ettiğine karar verirken hazırlığı, gerçek çalışmayı ve ara vermeyi ayrı tut. Her birinin ne olduğu açık olsun.","Bir çalışmada tek bir fırsatı kaçırmak, modellenen alışkanlık oluşumunu belirgin biçimde bozmadı. Bu, uzun araların zararsız olduğunu göstermez. Sana uyan düzeni tekrar kullan, uygun olmayan anı değiştir veya hedefine yeniden bak. Sıradaki yararlı işi ne zaman yapacağını seç. Telafi için iki kat çalışman gerekmiyor. Dinlenme hakkını da çalışarak kazanmak zorunda değilsin."],example:{title:"Leyla’nın sıradaki zamanı",text:"Pazar günü Leyla meslek belgesi için yaptığı plana bakıyor. Yemek sonrası ayırdığı zaman iki kez işe yaramış. Vardiya değişikliği yüzünden iki denemeyi yapamamış. Hedefini hâlâ sürdürmek istiyor. Bir soruyu pazartesi öğle molasında cevaplamayı planlıyor. Kullanabildiği notları da yanında olacak. Sonraki denemenin zamanını yazıyor. Aksayan çalışmaları yapılmış saymıyor. Pazartesi yapacağı iş kayıtta henüz bir plan olarak duruyor."}},move:{invitation:"Kaydına bak. Aynı işe yarayan küçük adım için gerçekten uygun bir tarih belirle.",instructions:["Denemelerinde sorun çıkaran tek bir koşulu değiştir. Seçtiğin günün ve ortamın uygun olduğunu kontrol et.","Plan yalnızca bu denemeyi ve ertesi gün değerlendirmesini kapsar. Haftalık değerlendirme sana kalır."],prompts:[],suggestions:{action:["Örnek: kaydettiğim meslek sınavı sorusunu cevapla","Kaydettiğim kısa yürüyüşe çık","Üzerime aldığım mutfak temizliğini yap"],minimum:["Aynı deneme sorusuna bir cevap yaz","Aynı güvenli beş dakikalık yolda yürü","Üzerime aldığım aynı iki kupayı yıka"],cue:["Kesinleşen 12.30 öğle molam başlayınca","Saati belli olan öğle molam başlayınca","Birlikte yediğimiz yemek bittikten hemen sonra"],place:["Molada kullanabildiğim masada","İşyerimde yürüyebildiğim aynı güzergahta","Kullanabildiğim mutfak lavabosunda"],minutes:[2,5],fallback:["Öğle molası iptal olursa uygun başka saat belirle","Yol güvenli değilse oturarak hareket etmeyi seç","Yapamıyorsam yararlı başka bir temizlik işi için anlaş"],observation:["Yeni başlama anında aynı soruyu cevaplayabildim mi","Yaptığım hareket ve ayırabildiğim süre","Yapılan iş ve ortamın uygun olup olmadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",cue:"Kesinleşen 12.30 öğle molam başlayınca",place:"Molada kullanabildiğim masada",fallback:"Öğle molası iptal olursa uygun başka saat belirle",observation:"Yeni başlama anında aynı soruyu cevaplayabildim mi",minutes:2},{action:"Kaydettiğim kısa yürüyüşe çık",minimum:"Aynı güvenli beş dakikalık yolda yürü",cue:"Saati belli olan öğle molam başlayınca",place:"İşyerimde yürüyebildiğim aynı güzergahta",fallback:"Yol güvenli değilse oturarak hareket etmeyi seç",observation:"Yaptığım hareket ve ayırabildiğim süre",minutes:5},{action:"Üzerime aldığım mutfak temizliğini yap",minimum:"Üzerime aldığım aynı iki kupayı yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğim mutfak lavabosunda",fallback:"Yapamıyorsam yararlı başka bir temizlik işi için anlaş",observation:"Yapılan iş ve ortamın uygun olup olmadığı",minutes:2}]},suggested:{action:"Örnek: kaydettiğim meslek sınavı sorusunu cevapla",minimum:"Aynı deneme sorusuna bir cevap yaz",minutes:2,cueHint:"Kesinleşen 12.30 öğle molam başlayınca",placeHint:"Molada kullanabildiğim masada",obstacleHint:"Örnek: vardiyam değişti, akşam çalışmaya ayırdığım zaman kalmadı",fallbackHint:"Öğle molası iptal olursa uygun başka saat belirle",observationHint:"Yeni başlama anında aynı soruyu cevaplayabildim mi"},stopRule:"Uzun süren ilgi kaybı veya günlük işlerde zorlanma varsa şimdi destek alabilirsin. Acil tehlikede hemen yardım iste.",accessibleAlternative:"Kullanabildiğin malzemeyi, kararlaştırılmış yardımı, destek isteğini, dinlenmeyi veya açıkça ara vermeyi seçebilirsin."},result:{question:"Seçtiğin geri dönüşü gerçekten yaptın mı?",observationPrompt:"Hangi gerçek davranışı, desteği veya ara vermeyi kaydettin?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"Kerem’in yeni vardiyası akşam yemeği bitmeden başlıyor; yürüyüş zamanı kalmıyor. Yürümeyi hâlâ seçiyor. Her gün öğle molasında güvenli beş dakikalık yol var. Vardiya öncesi yol erken kalkmayı gerektiriyor; pazar daha uzun yol uygun. Uykusunu azaltmadan hafta içi geri dönmeyi sınamak istiyor.",question:"Kaydındaki engele ve vereceği emeğe hangi plan uyuyor?",options:[{id:"motivation-5-early-walk",text:"Yürüyüşü vardiya öncesine alsın, yeni başlama anını korumak için alarmını her zamankinden erkene kursun.",feedback:"Vardiya öncesi yol, akşam çakışmasını çözer. Ama erken alarm uyku için koyduğu sınırla çelişir. Mevcut öğle molası, bu ek bedel olmadan hafta içi geri dönmeyi sınamasına izin verir."},{id:"motivation-5-sunday-walk",text:"Pazar günkü daha uzun yürüyüşe geçsin, haftada bir yapmanın programına daha iyi uyup uymadığına baksın.",feedback:"Haftalık yürüyüş, yapılabilir bir hedef değişikliği olabilir; başarısızlık değildir. Kerem şu an hafta içini sınamak istiyor ve öğle molası uygun. Sıklığı değiştirmeden önce bu koşulu denesin."},{id:"motivation-5-lunch-return",text:"Sıradaki öğle molasını seçsin, güvenli beş dakikalık yürüyüşü yapsın ve yeni saatin uyup uymadığını kaydetsin.",feedback:"Bu seçim yürüyüşü ve işe yarayan küçük kısmını korurken uygun olmayan akşam saatini değiştiriyor. Yalnızca yapılan yürüyüş uygulama sayılır. Yarınki değerlendirme bu düzeni tekrarlamak, değiştirmek veya bırakmak için bilgi verebilir."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Nedenini ve işe yarayan adımını koru. Kaydına bakıp, uymayan tek bir koşulu değiştir.",followUp:{questionId:"motivation-5-return",question:"Yeni başlama anı uydu mu? Hedef gelecek hafta da vereceğin zaman ve enerjiye değer mi?",observationPrompt:"Hangi gerçek davranışı, desteği veya ara vermeyi kaydettin?",adjustmentPrompt:"Sonraki denemenin sana uyması için neyi değiştirebilirsin? Tek bir şey seç."}},goDeeper:{sections:[{heading:"Kayıtları birleştir, yapılmamış bir seri yaratma",paragraphs:["Harkin ve çalışma arkadaşlarının 138 rastgele atamalı araştırmayı kapsayan derlemesinde ilerlemeyi izlemek, hedefe ulaşmada ortalama fayda gösterdi. Hedefler ve yöntemler farklıydı. Kayıt tutma ve sonuçları bildirme gibi özellikler, daha büyük etkilerle ilişkiliydi. Ama bunlar herkesle paylaşmanın veya haftalık sıklığın şart olduğunu göstermiyor. ODA’nın ertesi gün dönüşü bir uyarlamadır; araştırmayla doğrulanmış bir süre değildir. Haftalık değerlendirme isteğe bağlıdır, bu plan onu kendiliğinden takvime koymaz. [M13]","Lally’nin gözlem çalışmasında tek bir fırsatı kaçırmak, modellenen alışkanlık oluşumunu belirgin biçimde bozmadı. Bu dar sonuç, uzun araların alışkanlığı hiç değiştirmediğini kanıtlamaz. [M05] Sonraki adımı kendi denemelerine bakarak seç. İşe yarayan kısmı koru, uymayan başlama anını veya yanıtını değiştir, geçmişte yapılmayanları kayıtta bırak. Gelecek için kaydettiğin iş, hâlâ yalnızca bir plan. Hedef artık ayıracağın zamana değmiyorsa bilinçli biçimde değiştir, ertele veya bırak. Dersi bitirmek, işi yapmak ve denemeyi değerlendirmek ayrı şeylerdir."]},{heading:"Keyif şart değil, destek şimdi de mümkün",paragraphs:["Son ders, yeni bir motivasyon ritüeli eklemek yerine aynı denemeyi toparlıyor. İzleme araştırmaları gerçek ilerlemeyi seçilmiş bir hedefle karşılaştırmanın ortalama olarak yararlı olabildiğini gösterir. Her kişi için en iyi tekniği söylemez. Kaydın, başlama anının uygun olmadığını, malzemenin eksik kaldığını veya hedefin alacağı zamanın artık uymadığını gösterebilir. Sonraki tek değişikliği bu görülen koşula göre seç. Hazırlığı veya verilen sözü, davranışın kendisi olarak sayma. [M13]","Dinlenmeyi veya bütün keyifli etkinlikleri önce iş bitirme şartına bağlama. Daha sonra uygun, ücretsiz bir ses içeriği dinlersen trafikte çevrene ve güvenliğine dikkat et. Uzun süren ilgi kaybı, sıkıntı, bitkinlik veya günlük işleri tamamlamakta zorlanma, uzman değerlendirmesi gerektirebilir. NIMH rehberi destek istemeyi, acil tehlikede hemen yardım almayı önerir. Yalnızca isteksizliğe bakıp nedenini teşhis etmez, yardım istemeden önce beklemeni de şart koşmaz. [M20] Bu konuyla ilgilenirken küçük yararlı uygulamanı sürdürebilir, destek isteyebilir veya ara verebilirsin."]}],sourceIds:["M13","M05","M20"]}}];function n(a,r,d){const l=a.judgment.primary,e=[...l.options],m=e.findIndex(t=>t.id===l.bestOptionId);return[e[r],e[m]]=[e[m],e[r]],{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,practice:[a.move.instructions[0],a.move.instructions[1],"Gerçekte ne olduğunu kaydet. Yarın aynı denemeye geri bak."],reflection:a.direction.reason.label,question:`${l.scenario} ${l.question}`,options:e.map(t=>t.text),correct:r,feedback:e[r].feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,photo:d}}const s={id:"motivation",title:"Yine mi heves bekliyorsun? Hedefine bugün zaman ayır.",subtitle:"5 ders. Emeğine değen hedefi seç, işe yarayan küçük adımı dene, düzenini haftana uydur.",description:"Neye emek vermek istediğini seç. Küçük ama işe yarayan bir iş yap. Gerçekte olanlara göre başlama anını veya desteği değiştir.",scope:"Günlük hedefler için eğitim. Sürekli isteksizlik, bitkinlik veya günlük işlerini yapamama yalnızca motivasyon sorunu olmayabilir. Destek almak uygundur; bir sağlık uzmanı nedenini anlamana yardımcı olabilir.",outcome:"Kendi kayıtlarına göre şekillendirdiğin bir davranış ve tarihini belirlediğin sıradaki deneme.",photo:{id:"1790004245013-b347139d5591",alt:"Güneşli orman yolunda koşan bir adam"},lang:"tr",lessons:[n(i[0],1,{id:"1517971129774-8a2b38fa128e",alt:"Pencere yanında defterine yazan bir kadın"}),n(i[1],2,{id:"1581578731509-8ae9c5a3e7d3",alt:"Kapının yanında duran bir çift ayakkabı"}),n(i[2],2,{id:"1499933374294-4584851497cc",alt:"Masada siyah bir çalar saat"}),n(i[3],1,{id:"1575478004055-999ebe26dab7",alt:"Yağmurda şemsiyeyle yürüyen bir kadın"}),n(i[4],0,{id:"1577950248429-7530424d9682",alt:"Panoya asılmış bir aylık takvim"})]};export{s as COURSE,i as LESSONS_V2,k as SOURCES};
